package funcs

import (
	"fmt"
	"os"
	"strings"
)

// Env is the env namespace object. Methods become template functions
// like env.Getenv.
type Env struct{}

func init() {
	env := Env{}
	RegisterNS("env", func(deps *Deps) interface{} { return env })
	RegisterGlobal("getenv", env.Getenv)
}

// Env returns a map of all environment variables.
func (Env) Env() map[string]string {
	env := make(map[string]string)
	for _, e := range os.Environ() {
		kv := strings.SplitN(e, "=", 2)
		if len(kv) == 2 {
			env[kv[0]] = kv[1]
		}
	}
	return env
}

// Getenv returns the value of the environment variable named by key. If the
// variable is unset or empty, the contents of the file named by the key's
// _FILE variant are used. Otherwise the first default (or an empty string)
// is returned.
func (Env) Getenv(key interface{}, def ...string) string {
	val := os.Getenv(toString(key))
	if val == "" {
		val = readEnvFile(toString(key))
	}
	if val == "" && len(def) > 0 {
		val = def[0]
	}
	return val
}

// HasEnv reports whether the environment variable named by key is set.
// A variable set to an empty string is still considered set.
func (Env) HasEnv(key interface{}) bool {
	_, ok := os.LookupEnv(toString(key))
	return ok
}

// ExpandEnv replaces ${var} or $var in the input string according to the
// values of the current environment variables, using the same _FILE
// fallback as Getenv.
func (Env) ExpandEnv(input interface{}) string {
	e := Env{}
	return os.Expand(toString(input), func(key string) string {
		return e.Getenv(key)
	})
}

// readEnvFile reads the contents of the file named by the key's _FILE
// variant, trimming trailing CR/LF characters. Returns "" when the _FILE
// variable is unset or the file cannot be read.
func readEnvFile(key string) string {
	if file, ok := os.LookupEnv(key + "_FILE"); ok {
		b, err := os.ReadFile(file)
		if err == nil {
			return strings.TrimRight(string(b), "\r\n")
		}
	}
	return ""
}

// toString converts a template argument to a string.
func toString(in interface{}) string {
	if s, ok := in.(string); ok {
		return s
	}
	if b, ok := in.([]byte); ok {
		return string(b)
	}
	return fmt.Sprintf("%v", in)
}

package funcs

import (
	"os"
	"path/filepath"
	"testing"
)

func TestEnvGetenv(t *testing.T) {
	t.Setenv("GOMP_TEST_SET", "value")
	t.Setenv("GOMP_TEST_EMPTY", "")

	e := Env{}
	if got := e.Getenv("GOMP_TEST_SET"); got != "value" {
		t.Errorf("Getenv(set) = %q, want %q", got, "value")
	}
	if got := e.Getenv("GOMP_TEST_UNSET"); got != "" {
		t.Errorf("Getenv(unset) = %q, want %q", got, "")
	}
	if got := e.Getenv("GOMP_TEST_UNSET", "dflt"); got != "dflt" {
		t.Errorf("Getenv(unset, dflt) = %q, want %q", got, "dflt")
	}
	if got := e.Getenv("GOMP_TEST_UNSET", "dflt", "ignored"); got != "dflt" {
		t.Errorf("Getenv(unset, dflt, ignored) = %q, want %q", got, "dflt")
	}
	// an empty-valued variable falls through to the default
	if got := e.Getenv("GOMP_TEST_EMPTY", "dflt"); got != "dflt" {
		t.Errorf("Getenv(empty, dflt) = %q, want %q", got, "dflt")
	}
	// non-string keys are converted
	if got := e.Getenv(42); got != "" {
		t.Errorf("Getenv(42) = %q, want %q", got, "")
	}
}

func TestEnvGetenvFile(t *testing.T) {
	dir := t.TempDir()
	f := filepath.Join(dir, "secret")
	if err := os.WriteFile(f, []byte("safe\r\n"), 0o600); err != nil {
		t.Fatal(err)
	}
	t.Setenv("GOMP_TEST_FILEVAR_FILE", f)
	// direct value wins over the _FILE fallback
	t.Setenv("GOMP_TEST_DIRECT_FILE", f)
	t.Setenv("GOMP_TEST_DIRECT", "direct")
	t.Setenv("GOMP_TEST_MISSING_FILE", filepath.Join(dir, "nope"))

	e := Env{}
	// trailing CR/LF is trimmed from file contents
	if got := e.Getenv("GOMP_TEST_FILEVAR"); got != "safe" {
		t.Errorf("Getenv(_FILE) = %q, want %q", got, "safe")
	}
	if got := e.Getenv("GOMP_TEST_DIRECT"); got != "direct" {
		t.Errorf("Getenv(direct over _FILE) = %q, want %q", got, "direct")
	}
	if got := e.Getenv("GOMP_TEST_MISSING"); got != "" {
		t.Errorf("Getenv(missing file) = %q, want %q", got, "")
	}
	if got := e.Getenv("GOMP_TEST_MISSING", "dflt"); got != "dflt" {
		t.Errorf("Getenv(missing file, dflt) = %q, want %q", got, "dflt")
	}
}

func TestEnvHasEnv(t *testing.T) {
	t.Setenv("GOMP_TEST_SET", "value")
	t.Setenv("GOMP_TEST_EMPTY", "")

	e := Env{}
	if !e.HasEnv("GOMP_TEST_SET") {
		t.Error("HasEnv(set) = false, want true")
	}
	if !e.HasEnv("GOMP_TEST_EMPTY") {
		t.Error("HasEnv(empty) = false, want true (empty is still set)")
	}
	if e.HasEnv("GOMP_TEST_UNSET") {
		t.Error("HasEnv(unset) = true, want false")
	}
	if e.HasEnv(42) {
		t.Error("HasEnv(42) = true, want false")
	}
}

func TestEnvExpandEnv(t *testing.T) {
	t.Setenv("GOMP_TEST_SET", "value")

	e := Env{}
	if got := e.ExpandEnv("a $GOMP_TEST_SET b ${GOMP_TEST_SET} c $GOMP_TEST_UNSET"); got != "a value b value c " {
		t.Errorf("ExpandEnv = %q, want %q", got, "a value b value c ")
	}
	if got := e.ExpandEnv(42); got != "42" {
		t.Errorf("ExpandEnv(42) = %q, want %q", got, "42")
	}
}

func TestEnvEnv(t *testing.T) {
	t.Setenv("GOMP_TEST_SET", "value")

	m := Env{}.Env()
	if m["GOMP_TEST_SET"] != "value" {
		t.Errorf("Env()[GOMP_TEST_SET] = %q, want %q", m["GOMP_TEST_SET"], "value")
	}
	if _, ok := m["GOMP_TEST_UNSET"]; ok {
		t.Error("Env() contains unset variable")
	}
}
